const text = $json.output[0].content[0].text;

const headings = [
  "Meeting About",
  "Meeting Summary",
  "Good Points",
  "Bad Points",
  "Next Action",
  "Pending Items"
];

const result = {};

for (let i = 0; i < headings.length; i++) {
  const start = headings[i];
  const end = headings[i + 1];

  const startIndex = text.indexOf(start);

  if (startIndex === -1) {
    result[start] = "";
    continue;
  }

  const from = startIndex + start.length;

  const to = end
    ? text.indexOf(end, from)
    : text.length;

  result[start] = text.substring(from, to).trim();
}

return [{
  json: result
}];

const event = $('Loop Over Items').first().json;
const meetings = $json.items;

const attendees = (event.attendees || []).map(a =>
    a.email.toLowerCase()
);

const eventStart = new Date(event.start.dateTime || event.start);

const matches = meetings.filter(meeting =>
    meeting.calendar_invitees.some(invitee =>
        attendees.includes(invitee.email.toLowerCase())
    )
);

if (!matches.length) {
    return [];
}

matches.sort((a, b) => {
    const da = Math.abs(new Date(a.recording_started_at) - eventStart);
    const db = Math.abs(new Date(b.recording_started_at) - eventStart);
    return da - db;
});

return [{
    json: {
        recording_id: matches[0].recording_id,
        meeting: matches[0]
    }
}];

