// Extract the 7 slides from the big text and output each slide as its own item

const raw = $input.first().json.content.parts[0].text;

// Split slides by "### Slide"
const parts = raw.split("### Slide").slice(1);

const output = parts.map((p, index) => {
  const lines = p.trim().split("\n").filter(l => l.trim() !== "");

  // Remove the slide number text like "1: Hook..."
  lines.shift();

  const finalText = lines.join("\n");

  return {
    json: {
      slide: index + 1,
      message: finalText
    }
  };
});

return output;

const text = $json.output[0].content[0].text;

const sections = {};

let currentHeading = "Introduction";
let buffer = [];

text.split("\n").forEach(line => {
    const heading = line.match(/^#+\s*(.+)/);

    if (heading) {
        sections[currentHeading] = buffer.join("\n").trim();
        currentHeading = heading[1].trim();
        buffer = [];
    } else {
        buffer.push(line);
    }
});

sections[currentHeading] = buffer.join("\n").trim();

return [
{
    json: sections
}
];
